SELECT id, 'kg_220', '{"kg":"kg_220"}'::jsonb, 'KG 200 Preparatory measures', '220 Public development', 25, '{"designation":"Public development","notes":"Pro rata costs due to statutory regulations (development charges/resident contributions) and costs due to public law contracts for\n- the procurement or acquisition of the development areas against payment by the organisation responsible for the public development,\n- the construction or modification of jointly used technical facilities (e.g. for the discharge of waste water and the supply of water, heat, gas, electricity and telecommunications),\n- the initial construction or expansion of public traffic areas, green spaces and other open spaces for public use.\nCost subsidies and connection costs should be shown separately.\nWhen acquiring a property that has already been developed, the value of the development costs incurred prior to the acquisition can be recognised in KG 110.","level":2,"parent_kg":"kg_200","kg1":"KG 200","kg2":"KG 220"}'::jsonb, '\hline 220 & Public development & \begin{tabular}{l}
Pro rata costs due to statutory regulations (development charges/resident contributions) and costs due to public law contracts for \\
- the procurement or acquisition of the development areas against payment by the organisation responsible for the public development, \\
- the construction or modification of jointly used technical facilities (e.g. for the discharge of waste water and the supply of water, heat, gas, electricity and telecommunications), \\
- the initial construction or expansion of public traffic areas, green spaces and other open spaces for public use. \\
Cost subsidies and connection costs should be shown separately. \\
When acquiring a property that has already been developed, the value of the development costs incurred prior to the acquisition can be recognised in KG 110.
\end{tabular} \\' FROM regulation_tables WHERE standard_code = 'DIN-276' AND edition = '2018-12' AND table_code = 'TABLE1'
