SELECT id, 'kg_300', '{"kg":"kg_300"}'::jsonb, 'KG 100–800 (1. Ebene)', '300 Building - Building constructions', 44, '{"designation":"Building - Building constructions","notes":"Construction services and supplies for the construction of buildings, engineering structures and infrastructure facilities, but excluding technical installations (KG 400)\nThis also includes the installations permanently connected to the building that serve the respective purpose, as well as the overarching measures associated with the building structures.\nThe building structures also include the roof, facade and interior greenery associated with the building. Outdoor facilities outside the building and landscaped open spaces belong to KG 500.\nIn the case of conversions and modernisations of building structures, this also includes the costs of partial demolition, repair, securing and dismantling work. The costs must be recognised in the relevant cost groups.","level":1,"parent_kg":null,"kg1":"KG 300","kg2":null}'::jsonb, '\hline 300 & Building - Building constructions & \begin{tabular}{l}
Construction services and supplies for the construction of buildings, engineering structures and infrastructure facilities, but excluding technical installations (KG 400) \\
This also includes the installations permanently connected to the building that serve the respective purpose, as well as the overarching measures associated with the building structures. \\
The building structures also include the roof, facade and interior greenery associated with the building. Outdoor facilities outside the building and landscaped open spaces belong to KG 500. \\
In the case of conversions and modernisations of building structures, this also includes the costs of partial demolition, repair, securing and dismantling work. The costs must be recognised in the relevant cost groups.
\end{tabular} \\' FROM regulation_tables WHERE standard_code = 'DIN-276' AND edition = '2018-12' AND table_code = 'TABLE1'
