SELECT id, 'kg_384', '{"kg":"kg_384"}'::jsonb, 'KG 380 Structural fixtures', '384 Mechanical installations', 107, '{"designation":"Mechanical installations","notes":"Mechanical installations (especially in civil engineering structures) that fulfil a special purpose of the structure in water supply (e.g. scraper for sedimentation tanks), in wastewater disposal (e.g. scraper for sedimentation tanks, chamber filter presses, surface aerators, gas desulphurisers, gas storage tanks), in waste disposal (e.g. shredders, waste compactors) and in hydraulic engineering (e.g. steel structures for locks and weirs, coarse and fine screens). Mechanical fixtures include the drives of the fixtures, unless included in KG 466.\nThe connection technology and the process technology are included in KG 400.","level":3,"parent_kg":"kg_380","kg1":"KG 300","kg2":"KG 380"}'::jsonb, '\hline 384 & Mechanical installations & \begin{tabular}{l}
Mechanical installations (especially in civil engineering structures) that fulfil a special purpose of the structure in water supply (e.g. scraper for sedimentation tanks), in wastewater disposal (e.g. scraper for sedimentation tanks, chamber filter presses, surface aerators, gas desulphurisers, gas storage tanks), in waste disposal (e.g. shredders, waste compactors) and in hydraulic engineering (e.g. steel structures for locks and weirs, coarse and fine screens). Mechanical fixtures include the drives of the fixtures, unless included in KG 466. \\
The connection technology and the process technology are included in KG 400.
\end{tabular} \\' FROM regulation_tables WHERE standard_code = 'DIN-276' AND edition = '2018-12' AND table_code = 'TABLE1'
