SELECT id, 'kg_500', '{"kg":"kg_500"}'::jsonb, 'KG 100–800 (1. Ebene)', '500 Outdoor facilities and open spaces', 194, '{"designation":"Outdoor facilities and open spaces","notes":"Construction services and supplies for the construction of outdoor facilities of buildings and open spaces that are separate and independent of the buildings, with the associated structural installations, building structures or technical facilities\nThis also includes fixtures and fittings that are permanently attached to structures and serve a special purpose, as well as overarching measures.\nThe costs of outdoor facilities and open spaces that are underbuilt (e.g. underground car parks, basements, tunnels) must be shown in the relevant cost groups.\nIn the case of conversions and modernisations of outdoor facilities and open spaces, this also includes the costs of partial demolition, repair, securing and dismantling work. The costs must be recognised in the relevant cost groups.\nOff-site traffic installations and technical installations for the development of the property belong to KG 200.\nThe facade, wall, roof and interior greenery associated with the building as well as landscaping installations belong to KG 300.\nStand-alone buildings of infrastructure facilities belong to KG 300 and KG 400.","level":1,"parent_kg":null,"kg1":"KG 500","kg2":null}'::jsonb, '\hline 500 & Outdoor facilities and open spaces & \begin{tabular}{l}
Construction services and supplies for the construction of outdoor facilities of buildings and open spaces that are separate and independent of the buildings, with the associated structural installations, building structures or technical facilities \\
This also includes fixtures and fittings that are permanently attached to structures and serve a special purpose, as well as overarching measures. \\
The costs of outdoor facilities and open spaces that are underbuilt (e.g. underground car parks, basements, tunnels) must be shown in the relevant cost groups. \\
In the case of conversions and modernisations of outdoor facilities and open spaces, this also includes the costs of partial demolition, repair, securing and dismantling work. The costs must be recognised in the relevant cost groups. \\
Off-site traffic installations and technical installations for the development of the property belong to KG 200. \\
The facade, wall, roof and interior greenery associated with the building as well as landscaping installations belong to KG 300. \\
Stand-alone buildings of infrastructure facilities belong to KG 300 and KG 400.
\end{tabular} \\' FROM regulation_tables WHERE standard_code = 'DIN-276' AND edition = '2018-12' AND table_code = 'TABLE1'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
